const $=id=>document.getElementById(id);let audio=null,lastAlert=-Infinity,above=false;
$('radarAlert').onchange=async()=>{if(!$('radarAlert').checked){await audio?.close().catch(()=>{});audio=null;return}try{const C=window.AudioContext||window.webkitAudioContext;if(C){audio=new C();await audio.resume()}$('radarAlertStatus').textContent=navigator.vibrate?'':'Чичиргээ энэ браузерт дэмжигдэхгүй; дуут дохио ашиглана.'}catch{$('radarAlertStatus').textContent='Дуут дохио нээгдсэнгүй.'}};
function refresh(){const live=$('magValue').textContent.trim()!==''&&$('magValue').textContent!=='—';const raw=live?Number($('magValue').textContent):null;const valid=raw!==null&&Number.isFinite(raw);const factor=$('radarUnit').value==='mg'?10:1;$('radarUnitLabel').textContent=factor===10?'mG':'µT';$('radarReading').textContent=valid?(raw*factor).toFixed(1):'—';for(const axis of ['X','Y','Z']){const text=$('mag'+axis).textContent;const n=Number.parseFloat(text);$('radar'+axis).textContent=valid&&Number.isFinite(n)?(n*factor).toFixed(1):'—'}$('radarDisc').style.setProperty('--radar-color',!valid?'#7d9099':raw>120?'#ff666d':raw>=60?'#ffbc5f':'#63edc8');const status=valid?(raw>120?'Соронзон орны өсөлт':'Соронзон хэмжилт'):$('magStatus').textContent;if($('radarStatus').dataset.source!==status){$('radarStatus').dataset.source=status;$('radarStatus').textContent=status}const high=valid&&raw>120;if(high&&!above&&$('radarAlert').checked&&performance.now()-lastAlert>5000){lastAlert=performance.now();if(navigator.vibrate)navigator.vibrate(300);if(audio?.state==='running'){const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=660;g.gain.setValueAtTime(.08,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.25);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.25)}}above=high}
setInterval(refresh,200);$('radarUnit').onchange=refresh;document.addEventListener('visibilitychange',()=>{if(document.hidden)audio?.suspend();else if($('radarAlert').checked)audio?.resume().catch(()=>{})});refresh();
